package com.dawnrise.school.announcement;
import com.dawnrise.school.school.exception.ResourceNotFoundException;
import org.springframework.dao.OptimisticLockingFailureException;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;
import java.time.OffsetDateTime;
import java.util.List;
@Service
public class SchoolAnnouncementService {
 private final NamedParameterJdbcTemplate jdbc; private final ObjectMapper json;
 public SchoolAnnouncementService(NamedParameterJdbcTemplate jdbc,ObjectMapper json){this.jdbc=jdbc;this.json=json;}
 public AnnouncementDtos.Create preview(AnnouncementDtos.Create request){validateTimes(request.scheduledAt(),request.expiresAt());plain(request.title());plain(request.body());request.audiences().forEach(this::validateAudience);return request;}
 @Transactional public AnnouncementDtos.View create(long org,long actor,AnnouncementDtos.Create request){validateTimes(request.scheduledAt(),request.expiresAt());String status=request.scheduledAt()==null?"DRAFT":"SCHEDULED";Long id=jdbc.queryForObject("INSERT INTO school_announcements(organization_id,title,body,severity,status,scheduled_at,expires_at,created_by_user_id) VALUES(:org,:title,:body,:severity,:status,:scheduled,:expires,:actor) RETURNING id",new MapSqlParameterSource().addValue("org",org).addValue("title",plain(request.title())).addValue("body",plain(request.body())).addValue("severity",request.severity().name()).addValue("status",status).addValue("scheduled",request.scheduledAt()).addValue("expires",request.expiresAt()).addValue("actor",actor),Long.class);for(var a:request.audiences()){validateAudience(a);jdbc.update("INSERT INTO school_announcement_audiences(organization_id,announcement_id,audience_type,audience_key) VALUES(:org,:id,:type,:key)",new MapSqlParameterSource("org",org).addValue("id",id).addValue("type",a.type().name()).addValue("key",a.key()));}audit(org,id,actor,"CREATED");if("SCHEDULED".equals(status)){enqueue(org,id,request,request.scheduledAt());audit(org,id,actor,"SCHEDULED");}return get(org,id);}
 @Transactional(readOnly=true) public AnnouncementDtos.View get(long org,long id){var rows=jdbc.query("SELECT * FROM school_announcements WHERE organization_id=:org AND id=:id",new MapSqlParameterSource("org",org).addValue("id",id),(rs,n)->new AnnouncementDtos.View(rs.getLong("id"),rs.getString("title"),rs.getString("body"),AnnouncementDtos.Severity.valueOf(rs.getString("severity")),rs.getString("status"),audiences(org,id),rs.getObject("scheduled_at",OffsetDateTime.class),rs.getObject("published_at",OffsetDateTime.class),rs.getObject("expires_at",OffsetDateTime.class),rs.getLong("version")));if(rows.isEmpty())throw new ResourceNotFoundException("Announcement not found");return rows.getFirst();}
 @Transactional(readOnly=true) public AnnouncementDtos.View getPublished(long org,long id){var value=get(org,id);if(!List.of("PUBLISHED","EXPIRED").contains(value.status()))throw new ResourceNotFoundException("Announcement not found");return value;}
 @Transactional(readOnly=true) public List<AnnouncementDtos.View> list(long org){return jdbc.queryForList("SELECT id FROM school_announcements WHERE organization_id=:org ORDER BY created_at DESC,id DESC LIMIT 100",new MapSqlParameterSource("org",org),Long.class).stream().map(id->get(org,id)).toList();}
 @Transactional public AnnouncementDtos.View schedule(long org,long actor,long id,AnnouncementDtos.Schedule request){validateTimes(request.scheduledAt(),request.expiresAt());var current=get(org,id);if(!List.of("DRAFT","SCHEDULED").contains(current.status()))throw new IllegalStateException("Announcement cannot be scheduled");if(jdbc.update("UPDATE school_announcements SET status='SCHEDULED',scheduled_at=:scheduled,expires_at=:expires,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE organization_id=:org AND id=:id AND version=:version",new MapSqlParameterSource("org",org).addValue("id",id).addValue("version",request.version()).addValue("scheduled",request.scheduledAt()).addValue("expires",request.expiresAt()))!=1)throw new OptimisticLockingFailureException("Announcement changed");enqueue(org,id,new AnnouncementDtos.Create(current.title(),current.body(),current.severity(),current.audiences(),request.scheduledAt(),request.expiresAt()),request.scheduledAt());audit(org,id,actor,"SCHEDULED");return get(org,id);}
 @Transactional public AnnouncementDtos.View publish(long org,long actor,long id,long version){var current=get(org,id);if(!List.of("DRAFT","SCHEDULED").contains(current.status()))throw new IllegalStateException("Announcement cannot be published");int changed=jdbc.update("UPDATE school_announcements SET status='PUBLISHED',published_at=CURRENT_TIMESTAMP,scheduled_at=NULL,updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE organization_id=:org AND id=:id AND version=:version",new MapSqlParameterSource("org",org).addValue("id",id).addValue("version",version));if(changed!=1)throw new OptimisticLockingFailureException("Announcement changed");jdbc.update("UPDATE school_notification_outbox SET status='CANCELLED',updated_at=CURRENT_TIMESTAMP WHERE source_type='ANNOUNCEMENT' AND source_id=:id AND organization_id=:org AND status='PENDING'",new MapSqlParameterSource("id",id).addValue("org",org));enqueue(org,id,new AnnouncementDtos.Create(current.title(),current.body(),current.severity(),current.audiences(),null,current.expiresAt()),OffsetDateTime.now());audit(org,id,actor,"PUBLISHED");return get(org,id);}
 @Transactional public AnnouncementDtos.View cancel(long org,long actor,long id,long version){var current=get(org,id);if(List.of("EXPIRED","CANCELLED").contains(current.status()))throw new IllegalStateException("Announcement cannot be cancelled");if(jdbc.update("UPDATE school_announcements SET status='CANCELLED',cancelled_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE organization_id=:org AND id=:id AND version=:version",new MapSqlParameterSource("org",org).addValue("id",id).addValue("version",version))!=1)throw new OptimisticLockingFailureException("Announcement changed");jdbc.update("UPDATE school_notification_outbox SET status='CANCELLED',updated_at=CURRENT_TIMESTAMP WHERE source_type='ANNOUNCEMENT' AND source_id=:id AND organization_id=:org AND status='PENDING'",new MapSqlParameterSource("id",id).addValue("org",org));audit(org,id,actor,"CANCELLED");return get(org,id);}
 @Transactional public int advance(){jdbc.update("INSERT INTO school_announcement_audit(organization_id,announcement_id,actor_user_id,action) SELECT organization_id,id,created_by_user_id,'PUBLISHED' FROM school_announcements WHERE status='SCHEDULED' AND scheduled_at<=CURRENT_TIMESTAMP",new MapSqlParameterSource());int published=jdbc.update("UPDATE school_announcements SET status='PUBLISHED',published_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE status='SCHEDULED' AND scheduled_at<=CURRENT_TIMESTAMP",new MapSqlParameterSource());jdbc.update("INSERT INTO school_announcement_audit(organization_id,announcement_id,actor_user_id,action) SELECT organization_id,id,created_by_user_id,'EXPIRED' FROM school_announcements WHERE status='PUBLISHED' AND expires_at<=CURRENT_TIMESTAMP",new MapSqlParameterSource());jdbc.update("UPDATE school_announcements SET status='EXPIRED',updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE status='PUBLISHED' AND expires_at<=CURRENT_TIMESTAMP",new MapSqlParameterSource());jdbc.update("UPDATE school_notification_outbox o SET status='CANCELLED',updated_at=CURRENT_TIMESTAMP FROM school_announcements a WHERE o.source_type='ANNOUNCEMENT' AND o.source_id=a.id AND a.status IN ('EXPIRED','CANCELLED') AND o.status='PENDING'",new MapSqlParameterSource());return published;}
 @Transactional(readOnly=true) public List<AnnouncementDtos.Audit> audit(long org,long id){get(org,id);return jdbc.query("SELECT action,actor_user_id,occurred_at FROM school_announcement_audit WHERE organization_id=:org AND announcement_id=:id ORDER BY occurred_at,id",new MapSqlParameterSource("org",org).addValue("id",id),(rs,n)->new AnnouncementDtos.Audit(rs.getString(1),rs.getLong(2),rs.getObject(3,OffsetDateTime.class)));}
 private List<AnnouncementDtos.Audience> audiences(long org,long id){return jdbc.query("SELECT audience_type,audience_key FROM school_announcement_audiences WHERE organization_id=:org AND announcement_id=:id ORDER BY id",new MapSqlParameterSource("org",org).addValue("id",id),(rs,n)->new AnnouncementDtos.Audience(AnnouncementDtos.AudienceType.valueOf(rs.getString(1)),rs.getString(2)));}
 private void enqueue(long org,long id,AnnouncementDtos.Create r,OffsetDateTime available){try{jdbc.update("INSERT INTO school_notification_outbox(source_type,source_id,organization_id,source_event_id,event_type,importance,heading,context,audience_spec,available_at) VALUES('ANNOUNCEMENT',:id,:org,:source,'SCHOOL_ANNOUNCEMENT',:importance,:heading,:context,CAST(:audience AS JSONB),:available) ON CONFLICT(source_type,source_id,organization_id) DO UPDATE SET status='PENDING',available_at=EXCLUDED.available_at,audience_spec=EXCLUDED.audience_spec,updated_at=CURRENT_TIMESTAMP",new MapSqlParameterSource("id",id).addValue("org",org).addValue("source","announcement:"+id).addValue("importance",r.severity().name()).addValue("heading",r.title()).addValue("context","Open Dawnrise to read this school announcement").addValue("audience",json.writeValueAsString(r.audiences())).addValue("available",available));}catch(Exception e){throw new IllegalStateException("Announcement delivery could not be queued",e);}}
 private void audit(long org,long id,long actor,String action){jdbc.update("INSERT INTO school_announcement_audit(organization_id,announcement_id,actor_user_id,action) VALUES(:org,:id,:actor,:action)",new MapSqlParameterSource("org",org).addValue("id",id).addValue("actor",actor).addValue("action",action));}
 private void validateTimes(OffsetDateTime scheduled,OffsetDateTime expires){if(scheduled!=null&&!scheduled.isAfter(OffsetDateTime.now()))throw new IllegalArgumentException("Scheduled time must be in the future");if(expires!=null&&!expires.isAfter(scheduled==null?OffsetDateTime.now():scheduled))throw new IllegalArgumentException("Expiry must be after publication");}
 private void validateAudience(AnnouncementDtos.Audience a){boolean key=List.of(AnnouncementDtos.AudienceType.ROLE,AnnouncementDtos.AudienceType.WING,AnnouncementDtos.AudienceType.GRADE,AnnouncementDtos.AudienceType.SECTION).contains(a.type());if(key!=(a.key()!=null&&!a.key().isBlank()))throw new IllegalArgumentException("Audience key is invalid");if(key&&!a.key().matches("[A-Z_0-9-]{1,80}"))throw new IllegalArgumentException("Audience key is invalid");}
 private String plain(String value){if(value.contains("<")||value.contains(">"))throw new IllegalArgumentException("Announcement text must be plain text");return value.trim();}
}
